import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"17、【隨】 震下兌上","description":"橫渠易說 - 17、【隨】 震下兌上","frontmatter":{"title":"17、【隨】 震下兌上","description":"橫渠易說 - 17、【隨】 震下兌上"},"headers":[],"relativePath":"classics/hengqu/019.md","filePath":"classics/hengqu/019.md"}'),l={name:"classics/hengqu/019.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_17、【隨】-震下兌上" tabindex="-1">17、【隨】 震下兌上 <a class="header-anchor" href="#_17、【隨】-震下兌上" aria-label="Permalink to “17、【隨】 震下兌上”">​</a></h1><h3 id="彖曰-隨-剛來而下柔-動而說-隨。大亨貞無咎而天下隨時-隨時之義大矣哉" tabindex="-1">彖曰：隨，剛來而下柔，動而說，隨。大亨貞無咎而天下隨時，隨時之義大矣哉! <a class="header-anchor" href="#彖曰-隨-剛來而下柔-動而說-隨。大亨貞無咎而天下隨時-隨時之義大矣哉" aria-label="Permalink to “彖曰：隨，剛來而下柔，動而說，隨。大亨貞無咎而天下隨時，隨時之義大矣哉!”">​</a></h3><h3 id="象曰-澤中有雷-隨-君子以嚮晦入宴息。" tabindex="-1">象曰：澤中有雷，隨，君子以嚮晦入宴息。 <a class="header-anchor" href="#象曰-澤中有雷-隨-君子以嚮晦入宴息。" aria-label="Permalink to “象曰：澤中有雷，隨，君子以嚮晦入宴息。”">​</a></h3><h3 id="上九-下居於初也-故曰-剛來下柔-。" tabindex="-1">上九，下居於初也，故曰“剛來下柔”。 <a class="header-anchor" href="#上九-下居於初也-故曰-剛來下柔-。" aria-label="Permalink to “上九，下居於初也，故曰“剛來下柔”。”">​</a></h3><h3 id="初九-官有渝-貞吉-出門交有功。-象曰-官有渝-從正吉也。-出門交有功-不失也。" tabindex="-1">初九，官有渝，貞吉，出門交有功。 象曰：“官有渝”，從正吉也。“出門交有功”，不失也。 <a class="header-anchor" href="#初九-官有渝-貞吉-出門交有功。-象曰-官有渝-從正吉也。-出門交有功-不失也。" aria-label="Permalink to “初九，官有渝，貞吉，出門交有功。 象曰：“官有渝”，從正吉也。“出門交有功”，不失也。”">​</a></h3><p>言凡所治務能變而任正，不膠柱也。處隨之初，為動之主，心無私系，故能動必擇義，善與人同者也。</p><h3 id="六二-系小子-失丈夫。-象曰-系小子-弗兼與也。" tabindex="-1">六二，系小子，失丈夫。 象曰：“系小子”，弗兼與也。 <a class="header-anchor" href="#六二-系小子-失丈夫。-象曰-系小子-弗兼與也。" aria-label="Permalink to “六二，系小子，失丈夫。 象曰：“系小子”，弗兼與也。”">​</a></h3><h3 id="六三-系丈夫-失小子。隨有求得-利居貞。-象曰-系丈夫-志舍下也。" tabindex="-1">六三，系丈夫，失小子。隨有求得，利居貞。 象曰：“系丈夫”，志舍下也。 <a class="header-anchor" href="#六三-系丈夫-失小子。隨有求得-利居貞。-象曰-系丈夫-志舍下也。" aria-label="Permalink to “六三，系丈夫，失小子。隨有求得，利居貞。 象曰：“系丈夫”，志舍下也。”">​</a></h3><p>舍小隨大，所求可得，必守正不邪乃吉。</p><h3 id="九四-隨有獲-貞兇。有孚在道-以明何咎-象曰-隨有獲-其義兇也。-有孚在道-明功也。" tabindex="-1">九四，隨有獲，貞兇。有孚在道，以明何咎! 象曰：“隨有獲”，其義兇也。“有孚在道”，明功也。 <a class="header-anchor" href="#九四-隨有獲-貞兇。有孚在道-以明何咎-象曰-隨有獲-其義兇也。-有孚在道-明功也。" aria-label="Permalink to “九四，隨有獲，貞兇。有孚在道，以明何咎! 象曰：“隨有獲”，其義兇也。“有孚在道”，明功也。”">​</a></h3><p>以陽居陰，利於比三則兇也。處隨之世，為眾所附，苟利其獲，兇之道也。能以信存道，則功業可明，無所咎矣。</p><h3 id="九五-孚於嘉-吉。-象曰-孚於嘉吉-位正中也。" tabindex="-1">九五，孚於嘉，吉。 象曰：“孚於嘉吉”，位正中也。 <a class="header-anchor" href="#九五-孚於嘉-吉。-象曰-孚於嘉吉-位正中也。" aria-label="Permalink to “九五，孚於嘉，吉。 象曰：“孚於嘉吉”，位正中也。”">​</a></h3><h3 id="上六-拘繫之-乃從維之-王用亨於西山。-象曰-拘繫之-上窮也。" tabindex="-1">上六，拘繫之，乃從維之，王用亨於西山。 象曰：“拘繫之”，上窮也。 <a class="header-anchor" href="#上六-拘繫之-乃從維之-王用亨於西山。-象曰-拘繫之-上窮也。" aria-label="Permalink to “上六，拘繫之，乃從維之，王用亨於西山。 象曰：“拘繫之”，上窮也。”">​</a></h3><p>處隨之世而剛正宅尊，善為眾信，故吉。或曰：孚於二則吉。</p>',14)])])}const p=e(l,[["render",t]]);export{b as __pageData,p as default};
